/*
 * sq_nodes.h
 *	  The parser's tree, made by sq as digres's own nodes.
 *
 * digres parses with sq (../sq), whose nodes are laid out as digres's:
 * the same tags, sizes and fields. sq_nodes.c, generated by sq, holds
 * that at compile time, and refuses what sq parses but digres has no
 * part of. parser.c is its one caller.
 *
 * src/include/parser/sq_nodes.h
 */
#ifndef SQ_NODES_CHECKS_H
#define SQ_NODES_CHECKS_H

struct sq_node_t;

/*
 * Raise an ERROR if node, a statement sq parsed, is or names something
 * digres has none of: a publication or a subscription. A SQL function's
 * BEGIN ATOMIC body is looked into, as it holds statements of its own.
 */
extern void sq_refuse_unsupported(const struct sq_node_t *node);

#endif /* SQ_NODES_CHECKS_H */
